		if !ok || pkg.Name != qualifier {
			return "", false
		}
		name = e.Sel.Name
	case *ast.Ident:
		if qualifier != "" {
			return "", false
		}
		name = e.Name
	default:
		return "", false
	}
	_, ok := interfaces[name]
	return name, ok
